\begin{tikzpicture}[every node/.style={font=\small}, scale=1]
  \node[draw, rounded corners, align=center, minimum width=3.1cm, minimum height=1cm] (change) at (0,2.3)
  {instantaneous\\change};

  \node[draw, rounded corners, align=center, minimum width=3.1cm, minimum height=1cm] (accum) at (6.6,2.3)
  {accumulated\\change};

  \node[draw, rounded corners, align=center, minimum width=3.1cm, minimum height=1cm] (approx) at (0,-0.3)
  {approximation\\and error};

  \node[draw, rounded corners, align=center, minimum width=3.1cm, minimum height=1cm] (models) at (6.6,-0.3)
  {models and\\differential equations};

  \node[draw, rounded corners, align=center, minimum width=3.1cm, minimum height=1cm] (boundary) at (3.3,-2.5)
  {boundary\\ideas};

  \draw[->, thick] (change) -- node[above] {integrate} (accum);
  \draw[->, thick] (accum) -- node[below] {differentiate} (change);

  \draw[->, thick] (change) -- (approx);
  \draw[->, thick] (approx) -- (models);
  \draw[->, thick] (models) -- (accum);

  \draw[->, thick] ([xshift=-10pt]accum.south west) -- ([xshift=8pt]boundary.north);
  \draw[->, thick] ([xshift=-8pt]boundary.north) -- ([xshift=10pt]change.south east);

  \node[align=center] at (3.3,3.25)
  {The final projects connect the main ideas of the book.};
\end{tikzpicture}
